class Solution {
public:
    vector<int> findAnagrams(string s, string p) {
        vector<int> res;
        map<char, int> need, win;
        for (char c : p) need[c]++;
        int m = p.size();
        for (int r = 0; r < (int)s.size(); r++) {
            win[s[r]]++;
            int l = r - m + 1;
            if (l < 0) continue;
            if (win == need) res.push_back(l);
            if (--win[s[l]] == 0) win.erase(s[l]);
        }
        return res;
    }
};
